{"command":"cd /tmp/opencode/models && python3 - <<'EOF'
import numpy as np
for i in list(range(1,8))+list(range(8,11)):
    fn = f"model_{i:02d}.npz"
    z = np.load(fn, allow_pickle=False)
    print(f"--- {fn}: keys={list(z.keys())}")
    for k in z.keys():
        a = z[k]
        try:
            print(f"   {k}: shape={a.shape} dtype={a.dtype} value={a if a.size==1 else a}")
        except Exception as e:
            print(f"   {k}: {e}")
EOF"}
